    /// <summary>
    /// Rewrites script-shaped agent code (spec/contract.md §3.1) into one ordinary compilation unit. #line directives
    /// keep every diagnostic and stack frame in the agent's own coordinates (<c>snippet.cs</c>).
    /// </summary>
