            sb.Append("#line ").Append(position.Line + 1).Append(" \"").Append(RoslynCSharpCompiler.SnippetFile).Append("\"\n");
            sb.Append(' ', position.Character);
            var start = sb.Length;
            sb.Append(text).Append('\n');
            return start;
